-- Synthetic customer records: continues from customer_id 600
-- to reach a total of 1000 customers.
-- Run 1st (before rentals and payments).

USE sakila;

-- Temporarily remove the `customer_create_date` trigger so the dates below are kept
-- instead of being overwritten with NOW().
DROP TRIGGER IF EXISTS `customer_create_date`;

-- All rows go in as one transaction: if anything fails, nothing is half-loaded,
-- so the file can simply be run again after fixing the problem.
START TRANSACTION;


COMMIT;

-- Restore the original Sakila trigger (DROP first so re-running never fails with
-- "Trigger already exists").
DROP TRIGGER IF EXISTS `customer_create_date`;
CREATE TRIGGER `customer_create_date` BEFORE INSERT ON `customer` FOR EACH ROW SET NEW.create_date = NOW();
